-- Shared assertions: run after profile-fixture.sql and the profile migration in a disposable DB.
set role authenticated;
select set_config('request.jwt.claim.sub', '11111111-1111-1111-1111-111111111111', false);
select public.profile_test_assert(
    public.fetch_or_create_my_profile('11111111-1111-1111-1111-111111111111') =
    public.fetch_or_create_my_profile('11111111-1111-1111-1111-111111111111'), 'first nickname remains stable');
select public.profile_test_assert(
    public.fetch_or_create_my_profile('11111111-1111-1111-1111-111111111111')->>'nickname' ~ '^[가-힣]{2,10}$', 'natural ramen nickname');
select public.profile_test_reject($q$select public.fetch_or_create_my_profile('22222222-2222-2222-2222-222222222222')$q$);
select public.profile_test_reject($q$select public.update_my_profile('22222222-2222-2222-2222-222222222222', '라멘')$q$);
select public.profile_test_reject($q$update public.public_profiles set approved_at = now()$q$);
select public.profile_test_reject($q$select avatar_path from public.public_profiles$q$);
select public.profile_test_reject($q$select accepted_at from public.public_profiles$q$);
select public.profile_test_reject($q$select public.update_my_profile('11111111-1111-1111-1111-111111111111', '이름열한글자초과입니다')$q$);
select public.profile_test_reject($q$select public.update_my_profile('11111111-1111-1111-1111-111111111111', ' 라멘')$q$);
insert into storage.objects(bucket_id, name) values ('profile-avatars','11111111-1111-1111-1111-111111111111/aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa.jpg');
select public.profile_test_reject($q$insert into storage.objects(bucket_id, name) values ('profile-avatars','22222222-2222-2222-2222-222222222222/aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa.jpg')$q$);
select public.profile_test_reject($q$insert into storage.objects(bucket_id, name) values ('profile-avatars','11111111-1111-1111-1111-111111111111/../fake.jpg')$q$);
select public.update_my_profile('11111111-1111-1111-1111-111111111111', '산책하는차슈', '11111111-1111-1111-1111-111111111111/aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa.jpg');
delete from storage.objects where bucket_id = 'profile-avatars';
select public.profile_test_assert((select count(*) = 1 from storage.objects where bucket_id = 'profile-avatars'), 'referenced photo survives cleanup');
update storage.objects set name = 'overwrite' where bucket_id = 'profile-avatars';
select public.profile_test_assert((select count(*) = 1 from storage.objects where name like '%.jpg'), 'photos cannot be overwritten');
reset role;
select public.profile_test_assert((select accepted_guidelines_version is null and accepted_at is null from public.public_profiles where user_id = '11111111-1111-1111-1111-111111111111'), 'profile creation grants no consent');
update public.public_profiles set approved_at = now(), accepted_guidelines_version = '2026-09-06', accepted_at = '2026-09-06' where user_id = '11111111-1111-1111-1111-111111111111';
set role authenticated;
select public.update_my_profile('11111111-1111-1111-1111-111111111111', '산책하는차슈');
reset role;
select public.profile_test_assert((select approved_at is not null from public.public_profiles where user_id = '11111111-1111-1111-1111-111111111111'), 'no-op preserves approval');
set role authenticated;
select public.update_my_profile('11111111-1111-1111-1111-111111111111', '춤추는라멘');
reset role;
select public.profile_test_assert((select approved_at is null and accepted_at = '2026-09-06' and accepted_guidelines_version = '2026-09-06' from public.public_profiles where user_id = '11111111-1111-1111-1111-111111111111'), 'nickname clears approval and preserves consent');
update public.public_profiles set approved_at = now() where user_id = '11111111-1111-1111-1111-111111111111';
set role authenticated;
select public.update_my_profile('11111111-1111-1111-1111-111111111111', '춤추는라멘', null, true);
reset role;
select public.profile_test_assert((select approved_at is null and avatar_path is null from public.public_profiles where user_id = '11111111-1111-1111-1111-111111111111'), 'photo removal clears approval');
update public.public_profiles set suspended_at = now() where user_id = '11111111-1111-1111-1111-111111111111';
set role authenticated;
select public.profile_test_reject($q$select public.update_my_profile('11111111-1111-1111-1111-111111111111', '시오라멘')$q$);
select set_config('request.jwt.claim.sub', '22222222-2222-2222-2222-222222222222', false);
select public.profile_test_assert((select count(*) = 0 from storage.objects where bucket_id = 'profile-avatars'), 'other users cannot read photos');
select public.profile_test_reject($q$select public.update_my_profile('22222222-2222-2222-2222-222222222222', '시오라멘', '11111111-1111-1111-1111-111111111111/aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa.jpg')$q$);
select public.profile_test_reject($q$select public.update_my_profile('22222222-2222-2222-2222-222222222222', '시오라멘', '22222222-2222-2222-2222-222222222222/aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa.jpg')$q$);
select set_config('request.jwt.claim.sub', '', false);
select public.profile_test_reject($q$select public.fetch_or_create_my_profile('11111111-1111-1111-1111-111111111111')$q$);
set role anon;
select public.profile_test_reject($q$select public.fetch_or_create_my_profile('11111111-1111-1111-1111-111111111111')$q$);
select public.profile_test_reject($q$select public.update_my_profile('11111111-1111-1111-1111-111111111111', '시오라멘')$q$);
select public.profile_test_assert((select count(*) = 0 from storage.objects where bucket_id = 'profile-avatars'), 'anon cannot read photos');
reset role;
select public.profile_test_assert((select not public and file_size_limit = 5242880 and allowed_mime_types = array['image/jpeg','image/png'] from storage.buckets where id = 'profile-avatars'), 'private bucket image restrictions');
